    demoViewing: 'Du siehst dir das Horoskop von {name} als Demo an.',
    demoSignup: 'Registriere dich, um deine eigenen Planetenlinien, Städtedeutungen und dein Geburtshoroskop zu sehen.',
    createMyChart: 'MEIN HOROSKOP ERSTELLEN',
    alreadyAccount: 'Ich habe bereits ein Konto',
    systemGuide: 'SYSTEMANLEITUNG',
    guideOverview: 'ÜBERSICHT',
    guideLines: 'LINIEN',
    guidePlanets: 'PLANETEN',
    guideZones: 'ZONEN',
    guideHowTo: 'ANLEITUNG',
    guideFaq: 'FAQ',
    startExploring: 'JETZT ENTDECKEN',
    whatIsNN: 'WAS IST NATAL NAVIGATOR',
    whatIsNNBody: 'Natal Navigator ist ein Astrokartografie-Tool, das dein Geburtshoroskop auf den Globus projiziert. Es zeigt dir, welche Städte und Regionen der Welt energetisch mit deinen Planetenpositionen übereinstimmen — wo deine Stärken verstärkt werden und wo Herausforderungen entstehen können.',
    whatIsAstro: 'WAS IST ASTROKARTOGRAFIE',
    whatIsAstroBody1: 'Astrokartografie (oder Orteastrologie) berechnet, wo jeder Planet in deinem Geburtshoroskop aufging, unterging, kulminierte oder an seinem tiefsten Punkt war — und projiziert diese Positionen als Linien über den Globus. In der Nähe dieser Linien zu leben oder zu reisen aktiviert die Energie des Planeten in deinem Leben.',
    whatIsAstroBody2: 'Dein Geburtshoroskop ist eine Momentaufnahme des Himmels zum exakten Zeitpunkt deiner Geburt. Die Positionen von Sonne, Mond und Planeten definieren deine Persönlichkeitsmerkmale, Stärken und Lebensthemen. Astrokartografie erweitert dies mit der Frage: Wo auf der Erde waren diese planetarischen Energien am stärksten?',
    fourLineTypes: 'DIE VIER LINIENTYPEN',
    fourLineTypesIntro: 'Jeder Planet erzeugt vier Linien auf dem Globus — eine für jede Achse. Der Linientyp bestimmt, welchen Lebensbereich die Energie des Planeten an diesem Ort aktiviert.',
    mcLine: 'Medium Coeli',
    mcLineDesc: 'Wo ein Planet kulminiert — sein höchster Punkt. Aktiviert Karriere, öffentliches Ansehen und Ehrgeiz. Die sichtbarste und nach außen gerichtete Energie.',
    icLine: 'Nadir',
    icLineDesc: 'Wo ein Planet an seinem tiefsten Punkt unter dem Horizont steht. Aktiviert häusliches Leben, emotionale Wurzeln und innere Sicherheit. Tiefe, private Energie.',
    ascLine: 'Aszendent',
    ascLineDesc: 'Wo ein Planet am östlichen Horizont aufging. Aktiviert Identität, Selbstausdruck und ersten Eindruck. Persönliche und physische Energie.',
    dcLine: 'Deszendent',
    dcLineDesc: 'Wo ein Planet am westlichen Horizont unterging. Aktiviert Partnerschaften, Beziehungen und Zusammenarbeit. Zwischenmenschliche Energie.',
    lineFootnote: 'MC & IC sind vertikale Meridianlinien (von Pol zu Pol). ASZ & DSZ sind gekrümmte Linien, die dem Horizont folgen.',
    planetaryEnergies: 'PLANETARISCHE ENERGIEN',
    planetaryEnergiesIntro: 'Jeder Planet regiert bestimmte Lebensthemen. Wenn du in der Nähe einer Planetenlinie lebst oder sie besuchst, wird die Energie dieses Planeten im entsprechenden Lebensbereich verstärkt.',
    zoneClassification: 'ZONENKLASSIFIZIERUNG',
    zoneClassificationIntro: 'Städte in der Nähe deiner Linien werden basierend auf der traditionellen Natur des Planeten in drei Zonen eingeteilt. Nutze diese als Orientierung, nicht als absolute Regeln.',
    thriveZoneDesc: 'Wohltätige Planetenlinien — Sonne (Vitalität, Anerkennung), Mond (emotionale Zugehörigkeit), Venus (Liebe, Schönheit) und Jupiter (Glück, Expansion). Jeder Planet aktiviert unterschiedliche Stärken je nach Achse.',
    neutralZoneDesc: 'Gemischte Energielinien — Merkur (Kommunikation, Intellekt) und einige Mars/Saturn/Uranus-Achsen. Effekte sind subtil und hängen von bewusstem Engagement ab.',
    cautionZoneDesc: 'Herausfordernde Planetenlinien — Saturn (Einschränkung), Mars (Konflikt), Neptun (Verwirrung), Pluto (Machtkämpfe) und bestimmte Uranus-Achsen (Instabilität). Kurzbesuche können Lektionen lehren; Langzeitaufenthalte erfordern Achtsamkeit.',
    howToUse: 'SO WIRD\'S GENUTZT',
    step1: 'Erstelle dein Horoskop',
    step1Desc: 'Registriere dich und gib dein genaues Geburtsdatum, Uhrzeit und Ort ein. Genauigkeit ist wichtig — schon 15 Minuten können deine Linien verschieben.',
    step2: 'Erkunde den Globus',
    step2Desc: 'Ziehen zum Drehen, Scrollen zum Zoomen. Deine Planetenlinien werden über den Globus projiziert. Jede farbige Linie steht für eine Planet-Achsen-Kombination.',
    step3: 'Klicke auf Städte',
    step3Desc: 'Städte in der Nähe deiner Linien erscheinen im unteren Panel. Klicke auf eine Stadt für eine detaillierte Deutung der planetarischen Energie an diesem Ort.',
    step4: 'Filtere nach Planet',
    step4Desc: 'Nutze die linke Seitenleiste, um Planeten ein-/auszuschalten, sie zu erweitern und nach Stärke-/Neutral-/Vorsichtszonen zu filtern.',
    step5: 'Lies dein Geburtshoroskop',
    step5Desc: 'Klicke auf „Geburtshoroskop", um deine Planetenpositionen zu sehen. Wechsle zu „Persönlichkeit" für detaillierte Deutungen — tippe auf einen Planeten, um zu erfahren, was er in deinem Zeichen und Haus bedeutet.',
    faqTitle: 'HÄUFIG GESTELLTE FRAGEN',
    faq1Q: 'Muss ich meine genaue Geburtszeit kennen?',
    faq1A: 'Ja. Deine Geburtszeit bestimmt den Aszendenten und die Häuserspitzen, die deine Linien erheblich verschieben. Wenn du deine genaue Zeit nicht kennst, prüfe deine Geburtsurkunde oder kontaktiere das Geburtskrankenhaus.',
    faq2Q: 'Wie nah muss ich an einer Linie sein?',
    faq2A: 'Der Einfluss ist innerhalb von 1-2° einer Linie am stärksten (etwa 100-200 km). Wir zeigen Städte bis zu 3,5° Entfernung, wobei die Signalstärke mit der Distanz abnimmt.',
    faq3Q: 'Kann ich auf einer „Vorsichts"-Linie leben?',
    faq3A: 'Das hängt vom Planeten ab. Saturnlinien bringen Schwere und langsamen Fortschritt. Marslinien erzeugen Konflikte. Neptunlinien lösen Klarheit auf. Plutonlinien erzwingen intensive Transformation. Kurzbesuche können wertvolle Lektionen lehren; Langzeitaufenthalte erfordern tiefes Selbstbewusstsein.',
    faq4Q: 'Was ist der Unterschied zwischen Globus- und Kartenansicht?',
    faq4A: 'Die Globusansicht zeigt die Erde in 3D für räumlichen Kontext. Die Kartenansicht entfaltet die Projektion flach, was es einfacher macht, Linien über Kontinente zu verfolgen und Regionen zu vergleichen.',
    faq5Q: 'Basiert das auf echter Astronomie?',
    faq5A: 'Ja. Planetenpositionen werden mit hochpräzisen astronomischen Algorithmen (astronomy-engine) berechnet, vergleichbar mit forschungsqualifizierten Ephemeridendaten. Astrokartografie wendet dann astrologische Interpretation auf diese Positionen an.',
    mcFull: 'Medium Coeli (Himmelsmitte)',
    mcAngleDesc: 'Der höchste Punkt am Himmel bei deiner Geburt. Repräsentiert Karriere, öffentliches Ansehen und wie die Welt deine Errungenschaften sieht. Auf deiner MC-Linie fühlst du dich beruflich ermächtigt und öffentlich anerkannt.',
    icFull: 'Imum Coeli (Nadir)',
    icAngleDesc: 'Der tiefste Punkt unter dem Horizont. Repräsentiert Zuhause, Wurzeln, Familie und inneres Gefühlsleben. Auf deiner IC-Linie fühlst du tiefes Zugehörigkeitsgefühl und emotionale Erdung.',
    ascFull: 'Aszendent (Aufgang)',
    ascAngleDesc: 'Der östliche Horizont bei deiner Geburt. Repräsentiert deine Identität, Selbstausdruck und ersten Eindruck. Auf deiner ASZ-Linie strahlt deine Persönlichkeit und andere sehen dein authentisches Selbst.',
    dcFull: 'Deszendent (Untergang)',
    dcAngleDesc: 'Der westliche Horizont, gegenüber dem Aszendenten. Repräsentiert Partnerschaften, Beziehungen und wie du dich mit anderen verbindest. Auf deiner DSZ-Linie bilden sich bedeutungsvolle Beziehungen und Allianzen auf natürliche Weise.',
