    guideLines: 'LIGNES',
    guidePlanets: 'PLANÈTES',
    guideZones: 'ZONES',
    guideHowTo: 'UTILISATION',
    guideFaq: 'FAQ',
    startExploring: 'COMMENCER L\'EXPLORATION',
    whatIsNN: 'QU\'EST-CE QUE NATAL NAVIGATOR',
    whatIsNNBody: 'Natal Navigator est un outil d\'astrocartographie qui projette votre thème natal sur le globe. Il révèle quelles villes et régions du monde sont énergétiquement alignées avec vos positions planétaires — montrant où vos forces sont amplifiées et où des défis peuvent surgir.',
    whatIsAstro: 'QU\'EST-CE QUE L\'ASTROCARTOGRAPHIE',
    whatIsAstroBody1: 'L\'astrocartographie (ou astrologie de localisation) calcule où chaque planète de votre thème natal se levait, se couchait, culminait ou était à son point le plus bas — et projette ces positions sous forme de lignes sur le globe. Vivre près de ces lignes ou les visiter active l\'énergie de la planète dans votre vie.',
    whatIsAstroBody2: 'Votre thème natal est un instantané du ciel au moment exact de votre naissance. Les positions du Soleil, de la Lune et des planètes définissent vos traits de personnalité, forces et thèmes de vie. L\'astrocartographie prolonge cela en demandant : où sur Terre ces énergies planétaires étaient-elles les plus fortes ?',
    fourLineTypes: 'LES QUATRE TYPES DE LIGNES',
    fourLineTypesIntro: 'Chaque planète produit quatre lignes sur le globe — une pour chaque angle. Le type de ligne détermine quel domaine de vie l\'énergie de la planète active à cet endroit.',
    mcLine: 'Milieu du Ciel',
    mcLineDesc: 'Où une planète culmine — son point le plus haut. Active la carrière, la réputation publique et l\'ambition. L\'énergie la plus visible et tournée vers l\'extérieur.',
    icLine: 'Nadir',
    icLineDesc: 'Où une planète est à son point le plus bas sous l\'horizon. Active la vie domestique, les racines émotionnelles et la sécurité intérieure. Énergie profonde et privée.',
    ascLine: 'Ascendant',
    ascLineDesc: 'Où une planète se levait à l\'horizon est. Active l\'identité, l\'expression de soi et les premières impressions. Énergie personnelle et physique.',
    dcLine: 'Descendant',
    dcLineDesc: 'Où une planète se couchait à l\'horizon ouest. Active les partenariats, les relations et la collaboration. Énergie interpersonnelle.',
    lineFootnote: 'MC & IC sont des lignes méridiennes verticales (de pôle à pôle). ASC & DC sont des lignes courbes qui suivent l\'horizon.',
    planetaryEnergies: 'ÉNERGIES PLANÉTAIRES',
    planetaryEnergiesIntro: 'Chaque planète gouverne des thèmes de vie spécifiques. Lorsque vous vivez près d\'une ligne planétaire ou la visitez, l\'énergie de cette planète est amplifiée dans le domaine de vie correspondant.',
    zoneClassification: 'CLASSIFICATION DES ZONES',
    zoneClassificationIntro: 'Les villes proches de vos lignes sont classées en trois zones selon la nature traditionnelle de la planète. Utilisez ces indications comme guide, pas comme règles absolues.',
    thriveZoneDesc: 'Lignes planétaires bénéfiques — Soleil (vitalité, reconnaissance), Lune (appartenance émotionnelle), Vénus (amour, beauté) et Jupiter (chance, expansion). Chaque planète active différentes forces selon l\'angle.',
    neutralZoneDesc: 'Lignes à énergie mixte — Mercure (communication, intellect) et certains angles Mars/Saturne/Uranus. Les effets sont subtils et dépendent de l\'engagement conscient.',
    cautionZoneDesc: 'Lignes planétaires difficiles — Saturne (restriction), Mars (conflit), Neptune (confusion), Pluton (luttes de pouvoir) et certains angles d\'Uranus (instabilité). Les visites courtes peuvent enseigner des leçons ; les séjours longs nécessitent de la vigilance.',
    faqTitle: 'FOIRE AUX QUESTIONS',
    faq1Q: 'Dois-je connaître mon heure de naissance exacte ?',
    faq1A: 'Oui. Votre heure de naissance détermine l\'Ascendant et les cuspides des maisons, qui décalent significativement vos lignes. Si vous ne connaissez pas votre heure exacte, vérifiez votre acte de naissance ou contactez l\'hôpital de naissance.',
    faq2Q: 'À quelle distance d\'une ligne dois-je me trouver ?',
    faq2A: 'L\'influence est la plus forte dans un rayon de 1 à 2° d\'une ligne (environ 100 à 200 km). Nous affichons les villes jusqu\'à 3,5° de distance, avec une force de signal décroissante.',
    faq3Q: 'Puis-je vivre sur une ligne de « prudence » ?',
    faq3A: 'Cela dépend de la planète. Les lignes de Saturne apportent lourdeur et progression lente. Les lignes de Mars créent des conflits. Les lignes de Neptune dissolvent la clarté. Les lignes de Pluton forcent une transformation intense. Les visites courtes enseignent des leçons précieuses ; les séjours longs exigent une profonde conscience de soi.',
    faq4Q: 'Quelle est la différence entre vue globe et carte ?',
    faq4A: 'La vue globe montre la Terre en 3D pour le contexte spatial. La vue carte déplie la projection à plat, facilitant le suivi des lignes à travers les continents et la comparaison des régions.',
    faq5Q: 'Est-ce basé sur une vraie astronomie ?',
    faq5A: 'Oui. Les positions planétaires sont calculées avec des algorithmes astronomiques de haute précision (astronomy-engine), comparables aux données d\'éphémérides de qualité recherche. L\'astrocartographie applique ensuite une interprétation astrologique à ces positions.',
    mcFull: 'Milieu du Ciel',
    mcAngleDesc: 'Le point le plus haut du ciel à votre naissance. Représente la carrière, la réputation publique et comment le monde perçoit vos réalisations.',
    icFull: 'Fond du Ciel (Nadir)',
    icAngleDesc: 'Le point le plus profond sous l\'horizon. Représente le foyer, les racines, la famille et la vie émotionnelle intérieure.',
