    whatIsNNBody: 'Natal Navigator è uno strumento di astrocartografia che proietta il tuo tema natale sul globo. Rivela quali città e regioni del mondo sono energeticamente allineate con le tue posizioni planetarie — mostrando dove i tuoi punti di forza sono amplificati e dove possono sorgere sfide.',
