    language: 'Lingua',
    fourLineTypes: 'I QUATTRO TIPI DI LINEE',
    fourLineTypesIntro: 'Ogni pianeta produce quattro linee sul globo — una per ogni angolo. Il tipo di linea determina quale area della vita l\'energia del pianeta attiva in quella posizione.',
    mcLine: 'Medio Cielo',
    mcLineDesc: 'Dove un pianeta culmina — il suo punto più alto. Attiva carriera, reputazione pubblica e ambizione. L\'energia più visibile e rivolta verso l\'esterno.',
    icLine: 'Nadir',
    icLineDesc: 'Dove un pianeta si trova nel punto più basso sotto l\'orizzonte. Attiva la vita domestica, le radici emotive e la sicurezza interiore. Energia profonda e privata.',
    ascLine: 'Ascendente',
    ascLineDesc: 'Dove un pianeta stava sorgendo sull\'orizzonte orientale. Attiva identità, espressione di sé e prime impressioni. Energia personale e fisica.',
    dcLine: 'Discendente',
    dcLineDesc: 'Dove un pianeta stava tramontando sull\'orizzonte occidentale. Attiva partnership, relazioni e collaborazione. Energia interpersonale.',
    lineFootnote: 'MC & IC sono linee meridiane verticali (da polo a polo). ASC & DC sono linee curve che seguono l\'orizzonte.',
    mcFull: 'Medio Cielo',
    mcAngleDesc: 'Il punto più alto nel cielo alla tua nascita. Rappresenta carriera, reputazione pubblica e come il mondo vede i tuoi successi. Sulla tua linea MC, ti senti professionalmente potenziato e pubblicamente riconosciuto.',
    icFull: 'Imum Coeli (Nadir)',
    icAngleDesc: 'Il punto più profondo sotto l\'orizzonte. Rappresenta casa, radici, famiglia e vita emotiva interiore. Sulla tua linea IC, senti un profondo senso di appartenenza e radicamento emotivo.',
    ascFull: 'Ascendente (Sorgente)',
    ascAngleDesc: 'L\'orizzonte orientale alla tua nascita. Rappresenta la tua identità, espressione di sé e prime impressioni. Sulla tua linea ASC, la tua personalità brilla e gli altri vedono il tuo vero sé.',
    dcFull: 'Discendente (Tramontante)',
    dcAngleDesc: 'L\'orizzonte occidentale, opposto all\'Ascendente. Rappresenta partnership, relazioni e come ti connetti con gli altri. Sulla tua linea DC, relazioni significative e alleanze si formano naturalmente.',
    faqTitle: 'DOMANDE FREQUENTI',
    faq1Q: 'Devo conoscere la mia ora di nascita esatta?', faq1A: 'Sì. La tua ora di nascita determina l\'Ascendente e le cuspidi delle case, che spostano significativamente le tue linee.',
    faq2Q: 'Quanto vicino a una linea devo trovarmi?', faq2A: 'L\'influenza è più forte entro 1-2° da una linea (circa 100-200 km). Mostriamo le città fino a 3,5° di distanza, con l\'intensità del segnale che diminuisce con la distanza.',
    faq3Q: 'Posso vivere su una linea di "cautela"?', faq3A: 'Dipende dal pianeta. Le linee di Saturno portano pesantezza e progressi lenti. Le linee di Marte creano conflitto. Le linee di Nettuno dissolvono la chiarezza. Le linee di Plutone forzano trasformazioni intense. Le visite brevi possono insegnare lezioni preziose; i soggiorni lunghi richiedono profonda consapevolezza di sé.',
    faq4Q: 'Qual è la differenza tra vista globo e mappa?', faq4A: 'La vista globo mostra la Terra in 3D per un contesto spaziale. La vista mappa appiattisce la proiezione, rendendo più facile tracciare le linee attraverso i continenti e confrontare le regioni.',
    faq5Q: 'Si basa su vera astronomia?', faq5A: 'Sì. Le posizioni planetarie sono calcolate con algoritmi astronomici di alta precisione (astronomy-engine), comparabili ai dati di effemeridi di livello scientifico. L\'astrocartografia applica poi l\'interpretazione astrologica a queste posizioni.',
    planetaryEnergies: 'ENERGIE PLANETARIE',
    planetaryEnergiesIntro: 'Ogni pianeta governa temi di vita specifici. Quando vivi vicino o visiti una linea planetaria, l\'energia di quel pianeta viene amplificata nella corrispondente area della tua vita.',
    zoneClassification: 'CLASSIFICAZIONE DELLE ZONE',
    zoneClassificationIntro: 'Le città vicine alle tue linee sono classificate in tre zone in base alla natura tradizionale del pianeta. Usale come guida, non come regole assolute.',
    thriveZoneDesc: 'Linee planetarie benefiche — Sole (vitalità, riconoscimento), Luna (appartenenza emotiva), Venere (amore, bellezza) e Giove (fortuna, espansione). Ogni pianeta attiva forze diverse a seconda dell\'angolo.',
    neutralZoneDesc: 'Linee ad energia mista — Mercurio (comunicazione, intelletto) e alcuni angoli di Marte/Saturno/Urano. Gli effetti sono sottili e dipendono dall\'impegno consapevole.',
    cautionZoneDesc: 'Linee planetarie impegnative — Saturno (restrizione), Marte (conflitto), Nettuno (confusione), Plutone (lotte di potere) e certi angoli di Urano (instabilità). Le visite brevi possono insegnare lezioni; i soggiorni lunghi richiedono consapevolezza.',
    howToUse: 'COME USARE',
    step1: 'Crea il tuo tema',
    step1Desc: 'Registrati e inserisci la tua data di nascita esatta, l\'ora e il luogo. La precisione conta — anche 15 minuti possono spostare le tue linee.',
    step2: 'Esplora il globo',
    step2Desc: 'Trascina per ruotare, scorri per zoomare. Le tue linee planetarie sono proiettate sul globo. Ogni linea colorata rappresenta una combinazione pianeta-angolo.',
    step3: 'Clicca sulle città',
    step3Desc: 'Le città vicine alle tue linee appaiono nel pannello inferiore. Clicca su qualsiasi città per ottenere una lettura dettagliata di cosa significa quell\'energia planetaria per te in quel luogo.',
    step4: 'Filtra per pianeta',
