    // Guide - Overview
    whatIsNN: 'QUÉ ES NATAL NAVIGATOR',
    whatIsNNBody: 'Natal Navigator es una herramienta de astrocartografía que proyecta tu carta natal sobre el globo. Revela qué ciudades y regiones del mundo están energéticamente alineadas con tus posiciones planetarias.',
    whatIsAstro: 'QUÉ ES LA ASTROCARTOGRAFÍA',
    whatIsAstroBody1: 'La astrocartografía (o astrología locacional) calcula dónde cada planeta de tu carta natal estaba ascendiendo, poniéndose, culminando o en su punto más bajo — y proyecta esas posiciones como líneas a lo largo del globo. Vivir cerca o viajar a estas líneas activa la energía del planeta en tu vida.',
    whatIsAstroBody2: 'Tu carta natal es una instantánea del cielo en el momento exacto de tu nacimiento. Las posiciones del Sol, la Luna y los planetas en ese momento definen tus rasgos de personalidad, fortalezas y temas de vida. La astrocartografía extiende esto preguntando: ¿dónde en la Tierra estas energías planetarias eran más fuertes?',

    // Guide - Lines
    fourLineTypes: 'LOS CUATRO TIPOS DE LÍNEAS',
    fourLineTypesIntro: 'Cada planeta produce cuatro líneas en el globo — una por cada ángulo. El tipo de línea determina qué área de la vida activa la energía del planeta en esa ubicación.',
    mcLine: 'Medio Cielo',
    mcLineDesc: 'Donde un planeta culmina — su punto más alto. Activa la carrera, la reputación pública y la ambición. La energía más visible y orientada al exterior.',
    icLine: 'Nadir',
    icLineDesc: 'Donde un planeta está en su punto más bajo bajo el horizonte. Activa la vida doméstica, las raíces emocionales y la seguridad interior. Energía profunda y privada.',
    ascLine: 'Ascendente',
    ascLineDesc: 'Donde un planeta ascendía en el horizonte oriental. Activa la identidad, la autoexpresión y las primeras impresiones. Energía personal y física.',
    dcLine: 'Descendente',
    dcLineDesc: 'Donde un planeta se ponía en el horizonte occidental. Activa las asociaciones, las relaciones y la colaboración. Energía interpersonal.',
    lineFootnote: 'MC e IC son líneas meridianas verticales (de polo a polo). ASC y DC son líneas curvas que siguen el horizonte.',

    // Guide - Planets
    planetaryEnergies: 'ENERGÍAS PLANETARIAS',
    planetaryEnergiesIntro: 'Cada planeta gobierna temas específicos de la vida. Cuando vives cerca o visitas una línea planetaria, la energía de ese planeta se amplifica en el área correspondiente de tu vida.',

    // Guide - Zones
    zoneClassification: 'CLASIFICACIÓN DE ZONAS',
    zoneClassificationIntro: 'Las ciudades cercanas a tus líneas se clasifican en tres zonas según la naturaleza tradicional del planeta. Úsalas como orientación, no como reglas absolutas.',
    thriveZoneDesc: 'Líneas planetarias benéficas — Sol (vitalidad, reconocimiento), Luna (pertenencia emocional), Venus (amor, belleza) y Júpiter (suerte, expansión). Cada planeta activa diferentes fortalezas según el ángulo.',
    neutralZoneDesc: 'Líneas de energía mixta — Mercurio (comunicación, intelecto) y algunos ángulos de Marte/Saturno/Urano. Los efectos son sutiles y dependen del compromiso consciente.',
    cautionZoneDesc: 'Líneas planetarias desafiantes — Saturno (restricción), Marte (conflicto), Neptuno (confusión), Plutón (luchas de poder) y ciertos ángulos de Urano (inestabilidad). Las visitas cortas pueden enseñar lecciones; las estancias largas requieren conciencia.',

    // Guide - How to use
    howToUse: 'CÓMO USAR',
    step1: 'Crea tu carta',
    step1Desc: 'Regístrate e ingresa tu fecha, hora y lugar de nacimiento exactos. La precisión importa — incluso 15 minutos pueden desplazar tus líneas.',
    step2: 'Explora el globo',
    step2Desc: 'Arrastra para rotar, desplaza para hacer zoom. Tus líneas planetarias se proyectan a lo largo del globo. Cada línea de color representa una combinación planeta-ángulo.',
    step3: 'Haz clic en las ciudades',
    step3Desc: 'Las ciudades cercanas a tus líneas aparecen en el panel inferior. Haz clic en cualquier ciudad para obtener una lectura detallada de lo que esa energía planetaria significa para ti allí.',
    step4: 'Filtra por planeta',
    step4Desc: 'Usa la barra lateral izquierda para activar/desactivar planetas, expandirlos para ver sus líneas individuales y filtrar por zonas de fuerza/neutral/precaución.',
    step5: 'Lee tu carta natal',
    step5Desc: 'Haz clic en "Carta natal" para ver tus posiciones planetarias. Cambia a "Tu carta natal" para lecturas detalladas — toca cualquier planeta para ver qué significa en tu signo y casa.',

    // Guide - FAQ
    faqTitle: 'PREGUNTAS FRECUENTES',
    faq1Q: '¿Necesito saber mi hora de nacimiento exacta?',
    faq1A: 'Sí. Tu hora de nacimiento determina el Ascendente y las cúspides de las casas, que desplazan tus líneas significativamente. Si no conoces tu hora exacta, consulta tu certificado de nacimiento o contacta al hospital de nacimiento.',
    faq2Q: '¿Qué tan cerca de una línea debo estar?',
    faq2A: 'La influencia es más fuerte dentro de 1-2° de una línea (aproximadamente 100-200 km). Mostramos ciudades hasta 3.5° de distancia, con la intensidad de la señal disminuyendo con la distancia.',
    faq3Q: '¿Puedo vivir en una línea de "precaución"?',
    faq3A: 'Depende del planeta. Las líneas de Saturno traen pesadez y progreso lento. Las de Marte crean conflicto. Las de Neptuno disuelven la claridad. Las de Plutón fuerzan una transformación intensa. Las visitas cortas pueden enseñar lecciones valiosas; las estancias largas requieren profunda autoconciencia.',
    faq4Q: '¿Cuál es la diferencia entre la vista de globo y mapa?',
    faq4A: 'La vista de globo muestra la Tierra en 3D para contexto espacial. La vista de mapa despliega la proyección plana, facilitando el seguimiento de líneas entre continentes y la comparación de regiones.',
    faq5Q: '¿Esto se basa en astronomía real?',
    faq5A: 'Sí. Las posiciones planetarias se calculan usando algoritmos astronómicos de alta precisión (astronomy-engine), comparables a datos de efemérides de grado investigativo. La astrocartografía luego aplica la interpretación astrológica a estas posiciones.',

    // Angle info
    mcFull: 'Medium Coeli (Medio Cielo)',
    mcAngleDesc: 'El punto más alto del cielo en tu nacimiento. Representa la carrera, la reputación pública y cómo el mundo ve tus logros. En tu línea MC, te sientes profesionalmente empoderado y públicamente reconocido.',
    icFull: 'Imum Coeli (Nadir)',
    icAngleDesc: 'El punto más profundo bajo el horizonte. Representa el hogar, las raíces, la familia y la vida emocional interior. En tu línea IC, sientes un profundo sentido de pertenencia y estabilidad emocional.',
    ascFull: 'Ascendente (Rising)',
    ascAngleDesc: 'El horizonte oriental en tu nacimiento. Representa tu identidad, autoexpresión y primeras impresiones. En tu línea ASC, tu personalidad brilla y los demás ven tu yo auténtico.',
    dcFull: 'Descendente (Setting)',
