    // Guide - Overview
    whatIsNN: 'NATAL NAVIGATOR NEDİR',
    whatIsNNBody: 'Natal Navigator, doğum haritanı küre üzerine yansıtan bir astrokartografi aracıdır. Hangi şehir ve bölgelerin gezegen konumlarınla enerjetik olarak uyumlu olduğunu ortaya çıkarır.',
    whatIsAstro: 'ASTROKARTOGRAFİ NEDİR',
    whatIsAstroBody1: 'Astrokartografi (veya konumsal astroloji), doğum haritandaki her gezegenin nerede yükseldiğini, battığını, zirveye ulaştığını veya en düşük noktasında olduğunu hesaplar — ve bu konumları küre üzerinde çizgiler olarak yansıtır. Bu çizgilerin yakınında yaşamak veya seyahat etmek, gezegenin enerjisini hayatında etkinleştirir.',
    whatIsAstroBody2: 'Doğum haritan, doğduğun tam anda gökyüzünün bir anlık görüntüsüdür. O andaki Güneş, Ay ve gezegenlerin konumları kişilik özelliklerini, güçlü yönlerini ve yaşam temalarını belirler. Astrokartografi bunu şu soruyu sorarak genişletir: Bu gezegen enerjileri Dünya\'nın neresinde en güçlüydü?',

    // Guide - Lines
    fourLineTypes: 'DÖRT ÇİZGİ TÜRÜ',
    fourLineTypesIntro: 'Her gezegen küre üzerinde dört çizgi üretir — her açı için bir tane. Çizgi türü, gezegenin enerjisinin o konumda hangi yaşam alanını etkinleştirdiğini belirler.',
    mcLine: 'Gökyüzü Ortası',
    mcLineDesc: 'Bir gezegenin zirveye ulaştığı yer — en yüksek noktası. Kariyer, kamusal itibar ve hırsı etkinleştirir. En görünür ve dışa dönük enerji.',
    icLine: 'Nadir',
    icLineDesc: 'Bir gezegenin ufkun altında en düşük noktasında olduğu yer. Ev yaşamı, duygusal kökler ve iç güvenliği etkinleştirir. Derin, özel enerji.',
    ascLine: 'Yükselen',
    ascLineDesc: 'Bir gezegenin doğu ufkunda yükseldiği yer. Kimlik, kendini ifade ve ilk izlenimleri etkinleştirir. Kişisel ve fiziksel enerji.',
    dcLine: 'Alçalan',
    dcLineDesc: 'Bir gezegenin batı ufkunda battığı yer. Ortaklıkları, ilişkileri ve iş birliğini etkinleştirir. Kişilerarası enerji.',
    lineFootnote: 'MC ve IC, dikey meridyen çizgileridir (kutuptan kutuba). ASC ve DC, ufku takip eden eğri çizgilerdir.',

    // Guide - Planets
    planetaryEnergies: 'GEZEGEN ENERJİLERİ',
    planetaryEnergiesIntro: 'Her gezegen belirli yaşam temalarını yönetir. Bir gezegen çizgisinin yakınında yaşadığında veya ziyaret ettiğinde, o gezegenin enerjisi hayatının ilgili alanında güçlenir.',

    // Guide - Zones
    zoneClassification: 'BÖLGE SINIFLANDIRMASI',
    zoneClassificationIntro: 'Çizgilerine yakın şehirler, gezegenin geleneksel doğasına göre üç bölgeye ayrılır. Bunları mutlak kurallar olarak değil, rehber olarak kullan.',
    thriveZoneDesc: 'Hayırlı gezegen çizgileri — Güneş (canlılık, tanınırlık), Ay (duygusal aidiyet), Venüs (aşk, güzellik) ve Jüpiter (şans, genişleme). Her gezegen açıya göre farklı güçleri etkinleştirir.',
    neutralZoneDesc: 'Karma enerjili çizgiler — Merkür (iletişim, zeka) ve bazı Mars/Satürn/Uranüs açıları. Etkiler incedir ve bilinçli katılıma bağlıdır.',
    cautionZoneDesc: 'Zorlu gezegen çizgileri — Satürn (kısıtlama), Mars (çatışma), Neptün (kafa karışıklığı), Plüton (güç mücadeleleri) ve belirli Uranüs açıları (istikrarsızlık). Kısa ziyaretler dersler verebilir; uzun konaklamalar farkındalık gerektirir.',

    // Guide - How to use
    howToUse: 'NASIL KULLANILIR',
    step1: 'Haritanı oluştur',
    step1Desc: 'Kayıt ol ve tam doğum tarihi, saati ve yerini gir. Hassasiyet önemlidir — 15 dakika bile çizgilerini kaydırabilir.',
    step2: 'Küreyi keşfet',
    step2Desc: 'Döndürmek için sürükle, yakınlaştırmak için kaydır. Gezegen çizgilerin küre üzerine yansıtılır. Her renkli çizgi bir gezegen-açı kombinasyonunu temsil eder.',
    step3: 'Şehirlere tıkla',
    step3Desc: 'Çizgilerine yakın şehirler alt panelde görünür. Herhangi bir şehre tıklayarak o gezegen enerjisinin senin için ne anlama geldiğine dair ayrıntılı bir okuma al.',
    step4: 'Gezegene göre filtrele',
    step4Desc: 'Sol kenar çubuğunu kullanarak gezegenleri aç/kapat, bireysel çizgilerini görmek için genişlet ve güç/nötr/dikkat bölgelerine göre filtrele.',
    step5: 'Doğum haritanı oku',
    step5Desc: '"Doğum Haritası"na tıklayarak gezegen konumlarını gör. Ayrıntılı okumalar için "Doğum Haritan"a geç — herhangi bir gezegene dokunarak burcunda ve evinde ne anlama geldiğini gör.',

    // Guide - FAQ
    faqTitle: 'SIKÇA SORULAN SORULAR',
    faq1Q: 'Tam doğum saatimi bilmem gerekiyor mu?',
    faq1A: 'Evet. Doğum saatin Yükselen burcu ve ev sınırlarını belirler, bunlar çizgilerini önemli ölçüde kaydırır. Tam saatini bilmiyorsan doğum belgeni kontrol et veya doğduğun hastaneyle iletişime geç.',
    faq2Q: 'Bir çizgiye ne kadar yakın olmam gerekir?',
    faq2A: 'Etki, bir çizginin 1-2° içinde (yaklaşık 100-200 km) en güçlüdür. 3,5°\'ye kadar uzaklıktaki şehirleri gösteriyoruz, sinyal gücü mesafeyle azalır.',
    faq3Q: '"Dikkat" çizgisinde yaşayabilir miyim?',
    faq3A: 'Gezegene bağlıdır. Satürn çizgileri ağırlık ve yavaş ilerleme getirir. Mars çizgileri çatışma yaratır. Neptün çizgileri netliği bulandırır. Plüton çizgileri yoğun dönüşüm dayatır. Kısa ziyaretler değerli dersler öğretebilir; uzun konaklamalar derin öz farkındalık gerektirir.',
    faq4Q: 'Küre ve harita görünümü arasındaki fark nedir?',
    faq4A: 'Küre görünümü mekansal bağlam için Dünya\'yı 3D\'de gösterir. Harita görünümü projeksiyonu düzleştirerek kıtalar arası çizgileri takip etmeyi ve bölgeleri karşılaştırmayı kolaylaştırır.',
    faq5Q: 'Bu gerçek astronomiye dayanıyor mu?',
    faq5A: 'Evet. Gezegen konumları, araştırma düzeyindeki efemeris verileriyle karşılaştırılabilir yüksek hassasiyetli astronomik algoritmalarla (astronomy-engine) hesaplanır. Astrokartografi daha sonra bu konumlara astrolojik yorumlama uygular.',

    // Angle info
    mcFull: 'Medium Coeli (Gökyüzü Ortası)',
    mcAngleDesc: 'Doğumunda gökyüzündeki en yüksek nokta. Kariyer, kamusal itibar ve dünyanın başarılarını nasıl gördüğünü temsil eder. MC çizginde profesyonel olarak güçlenmiş ve kamusal olarak tanınmış hissedersin.',
    icFull: 'Imum Coeli (Nadir)',
    icAngleDesc: 'Ufkun altındaki en derin nokta. Ev, kökler, aile ve iç duygusal yaşamı temsil eder. IC çizginde derin bir aidiyet ve duygusal köklenme hissedersin.',
    ascFull: 'Yükselen (Rising)',
