    whatIsNNBody: 'O Natal Navigator é uma ferramenta de astrocartografia que projeta seu mapa natal sobre o globo. Ele revela quais cidades e regiões do mundo estão energeticamente alinhadas com suas posições planetárias — mostrando onde seus potenciais são amplificados e onde desafios podem surgir.',
    whatIsAstro: 'O QUE É ASTROCARTOGRAFIA',
    whatIsAstroBody1: 'A astrocartografia (ou astrologia locacional) calcula onde cada planeta do seu mapa natal estava nascendo, se pondo, culminando ou no ponto mais baixo — e projeta essas posições como linhas ao redor do globo. Viver perto ou viajar para essas linhas ativa a energia do planeta na sua vida.',
    whatIsAstroBody2: 'Seu mapa natal é uma foto do céu no momento exato em que você nasceu. As posições do Sol, da Lua e dos planetas naquele momento definem seus traços de personalidade, pontos fortes e temas de vida. A astrocartografia estende isso perguntando: onde na Terra essas energias planetárias eram mais fortes?',

    // Guide - Lines
    fourLineTypes: 'OS QUATRO TIPOS DE LINHA',
    fourLineTypesIntro: 'Cada planeta produz quatro linhas no globo — uma para cada ângulo. O tipo de linha determina qual área da vida a energia do planeta ativa naquele local.',
    mcLine: 'Meio do Céu',
    mcLineDesc: 'Onde um planeta culmina — seu ponto mais alto. Ativa carreira, reputação pública e ambição. A energia mais visível e voltada para o exterior.',
    icLine: 'Nadir',
    icLineDesc: 'Onde um planeta está no ponto mais baixo abaixo do horizonte. Ativa vida doméstica, raízes emocionais e segurança interior. Energia profunda e privada.',
    ascLine: 'Ascendente',
    ascLineDesc: 'Onde um planeta estava nascendo no horizonte leste. Ativa identidade, autoexpressão e primeiras impressões. Energia pessoal e física.',
    dcLine: 'Descendente',
    dcLineDesc: 'Onde um planeta estava se pondo no horizonte oeste. Ativa parcerias, relacionamentos e colaboração. Energia interpessoal.',
    lineFootnote: 'MC e IC são linhas meridianas verticais (polo a polo). ASC e DC são linhas curvas que seguem o horizonte.',

    // Guide - Planets
    planetaryEnergies: 'ENERGIAS PLANETÁRIAS',
    planetaryEnergiesIntro: 'Cada planeta governa temas específicos da vida. Quando você mora perto ou visita uma linha planetária, a energia daquele planeta é amplificada na área correspondente da sua vida.',

    // Guide - Zones
    zoneClassification: 'CLASSIFICAÇÃO DE ZONAS',
    zoneClassificationIntro: 'Cidades próximas às suas linhas são classificadas em três zonas com base na natureza tradicional do planeta. Use-as como orientação, não como regras absolutas.',
    thriveZoneDesc: 'Linhas planetárias benéficas — Sol (vitalidade, reconhecimento), Lua (pertencimento emocional), Vênus (amor, beleza) e Júpiter (sorte, expansão). Cada planeta ativa diferentes pontos fortes dependendo do ângulo.',
    neutralZoneDesc: 'Linhas de energia mista — Mercúrio (comunicação, intelecto) e alguns ângulos de Marte/Saturno/Urano. Os efeitos são sutis e dependem de engajamento consciente.',
    cautionZoneDesc: 'Linhas planetárias desafiadoras — Saturno (restrição), Marte (conflito), Netuno (confusão), Plutão (lutas de poder) e certos ângulos de Urano (instabilidade). Visitas curtas podem ensinar lições; estadias longas exigem consciência.',

    // Guide - How to use
    howToUse: 'COMO USAR',
    step1: 'Crie seu mapa',
    step1Desc: 'Cadastre-se e insira sua data, hora e local exatos de nascimento. A precisão importa — mesmo 15 minutos podem deslocar suas linhas.',
    step2: 'Explore o globo',
    step2Desc: 'Arraste para girar, role para dar zoom. Suas linhas planetárias são projetadas ao redor do globo. Cada linha colorida representa uma combinação planeta-ângulo.',
    step3: 'Clique nas cidades',
    step3Desc: 'Cidades próximas às suas linhas aparecem no painel inferior. Clique em qualquer cidade para obter uma leitura detalhada do que aquela energia planetária significa para você ali.',
    step4: 'Filtre por planeta',
    step4Desc: 'Use a barra lateral esquerda para ativar/desativar planetas, expandi-los para ver suas linhas individuais e filtrar por zonas de força/neutro/cuidado.',
    step5: 'Leia seu mapa natal',
    step5Desc: 'Clique em "Mapa Natal" para ver suas posições planetárias. Mude para "Seu Mapa Natal" para leituras detalhadas — toque em qualquer planeta para ver o que significa no seu signo e casa.',

    // Guide - FAQ
    faqTitle: 'PERGUNTAS FREQUENTES',
    faq1Q: 'Preciso saber meu horário exato de nascimento?',
    faq1A: 'Sim. Seu horário de nascimento determina o Ascendente e as cúspides das casas, que deslocam suas linhas significativamente. Se não souber seu horário exato, verifique sua certidão de nascimento ou entre em contato com o hospital de nascimento.',
    faq2Q: 'Quão perto de uma linha eu preciso estar?',
    faq2A: 'A influência é mais forte dentro de 1-2° de uma linha (aproximadamente 100-200 km). Mostramos cidades até 3,5° de distância, com a intensidade do sinal diminuindo com a distância.',
    faq3Q: 'Posso morar em uma linha de "cuidado"?',
    faq3A: 'Depende do planeta. Linhas de Saturno trazem peso e progresso lento. Linhas de Marte criam conflito. Linhas de Netuno dissolvem a clareza. Linhas de Plutão forçam transformação intensa. Visitas curtas podem ensinar lições valiosas; estadias longas exigem profunda autoconsciência.',
    faq4Q: 'Qual a diferença entre o globo e a vista de mapa?',
    faq4A: 'A vista de globo mostra a Terra em 3D para contexto espacial. A vista de mapa abre a projeção plana, facilitando o rastreamento de linhas entre continentes e a comparação de regiões.',
    faq5Q: 'Isso é baseado em astronomia real?',
    faq5A: 'Sim. As posições planetárias são calculadas usando algoritmos astronômicos de alta precisão (astronomy-engine), comparáveis a dados de efemérides de nível de pesquisa. A astrocartografia então aplica interpretação astrológica a essas posições.',

    // Angle info
    mcFull: 'Medium Coeli (Meio do Céu)',
    mcAngleDesc: 'O ponto mais alto no céu no seu nascimento. Representa carreira, reputação pública e como o mundo vê suas conquistas. Na sua linha MC, você se sente profissionalmente empoderado e publicamente reconhecido.',
    icFull: 'Imum Coeli (Nadir)',
    icAngleDesc: 'O ponto mais profundo abaixo do horizonte. Representa lar, raízes, família e vida emocional interior. Na sua linha IC, você sente um profundo senso de pertencimento e ancoragem emocional.',
    ascFull: 'Ascendente (Nascente)',
    ascAngleDesc: 'O horizonte leste no seu nascimento. Representa sua identidade, autoexpressão e primeiras impressões. Na sua linha ASC, sua personalidade brilha e os outros veem seu eu autêntico.',
    dcFull: 'Descendente (Poente)',
    dcAngleDesc: 'O horizonte oeste, oposto ao Ascendente. Representa parcerias, relacionamentos e como você se conecta com os outros. Na sua linha DC, relacionamentos significativos e alianças se formam naturalmente.',

