    // Guide - Overview
    whatIsNN: 'ネイタルナビゲーターとは',
    whatIsNNBody: 'ネイタルナビゲーターは、あなたの出生チャートを地球上にマッピングするアストロカートグラフィーツールです。あなたの惑星配置とエネルギー的に整合する都市や地域を明らかにし、強みが増幅される場所や課題が生じる可能性のある場所を示します。',
    whatIsAstro: 'アストロカートグラフィーとは',
    whatIsAstroBody1: 'アストロカートグラフィー（ロケーショナル占星術）は、出生チャート内の各惑星が上昇、下降、南中、または最低点にあった地点を計算し、それらの位置をラインとして地球上に投影します。これらのラインの近くに住んだり旅行したりすると、その惑星のエネルギーがあなたの人生で活性化されます。',
    whatIsAstroBody2: 'あなたの出生チャートは、生まれた瞬間の空のスナップショットです。太陽、月、惑星のその時の位置が、あなたの性格特性、強み、人生のテーマを定義します。アストロカートグラフィーは、これらの惑星エネルギーが地球上のどこで最も強かったかを問うことで、これを拡張します。',

    // Guide - Lines
    fourLineTypes: '4つのラインタイプ',
    fourLineTypesIntro: '各惑星は地球上に4本のライン（各アングルに1本）を生成します。ラインタイプは、その場所で惑星のエネルギーがどの生活領域を活性化するかを決定します。',
    mcLine: 'ミッドヘブン',
    mcLineDesc: '惑星が南中する場所 — 最高点。キャリア、社会的評価、野心を活性化します。最も可視的で外向きのエネルギーです。',
    icLine: 'ネイディア',
    icLineDesc: '惑星が地平線下の最低点にある場所。家庭生活、感情的なルーツ、内面の安心感を活性化します。深く私的なエネルギーです。',
    ascLine: 'アセンダント',
    ascLineDesc: '惑星が東の地平線上で上昇していた場所。アイデンティティ、自己表現、第一印象を活性化します。個人的かつ身体的なエネルギーです。',
    dcLine: 'ディセンダント',
    dcLineDesc: '惑星が西の地平線上で下降していた場所。パートナーシップ、人間関係、協力を活性化します。対人的なエネルギーです。',
    lineFootnote: 'MC・ICは垂直の子午線ライン（極から極）です。ASC・DCは地平線に沿った曲線ラインです。',

    // Guide - Planets
    planetaryEnergies: '惑星のエネルギー',
    planetaryEnergiesIntro: '各惑星は特定の人生テーマを司ります。惑星ラインの近くに住んだり訪れたりすると、その惑星のエネルギーが対応する生活領域で増幅されます。',

    // Guide - Zones
    zoneClassification: 'ゾーン分類',
    zoneClassificationIntro: 'あなたのライン付近の都市は、惑星の伝統的な性質に基づいて3つのゾーンに分類されます。絶対的な法則ではなく、ガイダンスとしてお使いください。',
    thriveZoneDesc: '吉星の惑星ライン — 太陽（活力、認知）、月（感情的な帰属感）、金星（愛、美）、木星（幸運、拡大）。各惑星はアングルに応じて異なる強みを活性化します。',
    neutralZoneDesc: '混合エネルギーのライン — 水星（コミュニケーション、知性）および一部の火星/土星/天王星のアングル。効果は微妙で、意識的な関与に依存します。',
    cautionZoneDesc: '挑戦的な惑星ライン — 土星（制限）、火星（葛藤）、海王星（混乱）、冥王星（権力闘争）、および特定の天王星アングル（不安定性）。短期訪問は学びになりますが、長期滞在には自覚が必要です。',

    // Guide - How to use
    howToUse: '使い方',
    step1: 'チャートを作成',
    step1Desc: '登録して正確な出生日、出生時刻、出生地を入力します。精度が重要です — 15分のずれでもラインが移動します。',
    step2: '地球儀を探索',
    step2Desc: 'ドラッグで回転、スクロールでズーム。惑星ラインが地球上に投影されます。各色のラインは惑星とアングルの組み合わせを表します。',
    step3: '都市をクリック',
    step3Desc: 'ライン付近の都市が下部パネルに表示されます。都市をクリックすると、その場所での惑星エネルギーの詳細なリーディングが表示されます。',
    step4: '惑星でフィルター',
    step4Desc: '左サイドバーで惑星のオン/オフを切り替え、展開して個別のラインを表示し、活力/中立/注意ゾーンでフィルタリングします。',
    step5: 'ネイタルチャートを読む',
    step5Desc: '「ネイタルチャート」をクリックして惑星配置を確認。「あなたの出生チャート」に切り替えると詳細リーディングが表示されます — 惑星をタップしてサインとハウスの意味を確認しましょう。',

    // Guide - FAQ
    faqTitle: 'よくある質問',
    faq1Q: '正確な出生時刻が必要ですか？',
    faq1A: 'はい。出生時刻がアセンダントとハウスカスプを決定し、ラインを大きく移動させます。正確な時刻がわからない場合は、出生証明書を確認するか、出生した病院に問い合わせてください。',
    faq2Q: 'ラインからどのくらい近くにいる必要がありますか？',
    faq2A: '影響はラインから1〜2°以内（約100〜200km）で最も強くなります。3.5°離れた都市まで表示され、距離に応じてシグナル強度が低下します。',
    faq3Q: '「注意」ラインに住むことはできますか？',
    faq3A: '惑星によります。土星ラインは重さと遅い進展をもたらします。火星ラインは葛藤を生みます。海王星ラインは明晰さを失わせます。冥王星ラインは激しい変容を強います。短期訪問は貴重な学びになりますが、長期滞在には深い自己認識が必要です。',
    faq4Q: '地球儀ビューと地図ビューの違いは？',
    faq4A: '地球儀ビューは3Dで空間的なコンテキストを提供します。地図ビューは投影を平面に展開し、大陸をまたぐラインの追跡や地域の比較が容易になります。',
    faq5Q: '実際の天文学に基づいていますか？',
    faq5A: 'はい。惑星位置は高精度の天文計算アルゴリズム（astronomy-engine）を使用して計算され、研究レベルの天文暦データに匹敵します。アストロカートグラフィーはこれらの位置に占星術的解釈を適用します。',

