    whatIsNN: 'ما هو ناتال نافيجيتور',
    whatIsNNBody: 'ناتال نافيجيتور هو أداة خرائط فلكية تعرض خريطة ولادتك على الكرة الأرضية. يكشف عن المدن والمناطق في العالم المتوافقة طاقيًا مع مواقع كواكبك — ويُظهر أين تتعزز نقاط قوتك وأين قد تنشأ التحديات.',
    whatIsAstro: 'ما هي الخرائط الفلكية',
    whatIsAstroBody1: 'تحسب الخرائط الفلكية أين كان كل كوكب في خريطة ولادتك يشرق أو يغرب أو يتوج أو في أدنى نقطة — وتعرض تلك المواقع كخطوط عبر الكرة الأرضية. العيش بالقرب من هذه الخطوط أو زيارتها ينشّط طاقة الكوكب في حياتك.',
    whatIsAstroBody2: 'خريطة ولادتك هي لقطة للسماء في اللحظة الدقيقة لولادتك. مواقع الشمس والقمر والكواكب تحدد سماتك الشخصية ونقاط قوتك ومواضيع حياتك. الخرائط الفلكية توسع ذلك بالسؤال: أين على الأرض كانت هذه الطاقات الكوكبية أقوى؟',

    // Guide - Lines
