    // Guide - Zones
    zoneClassification: 'تصنيف المناطق',
    zoneClassificationIntro: 'تُصنَّف المدن القريبة من خطوطك إلى ثلاث مناطق بناءً على طبيعة الكوكب التقليدية. استخدمها كدليل وليس كقواعد مطلقة.',
    thriveZoneDesc: 'خطوط الكواكب المفيدة — الشمس (الحيوية، التقدير)، القمر (الانتماء العاطفي)، الزهرة (الحب، الجمال)، والمشتري (الحظ، التوسع). كل كوكب ينشّط نقاط قوة مختلفة حسب الزاوية.',
    neutralZoneDesc: 'خطوط طاقة مختلطة — عطارد (التواصل، الذكاء) وبعض زوايا المريخ/زحل/أورانوس. التأثيرات خفيفة وتعتمد على الوعي.',
    cautionZoneDesc: 'خطوط كوكبية صعبة — زحل (القيود)، المريخ (الصراع)، نبتون (الارتباك)، بلوتو (صراعات القوة)، وبعض زوايا أورانوس (عدم الاستقرار). الزيارات القصيرة تعلّم دروسًا؛ الإقامات الطويلة تتطلب وعيًا.',

