    step2: 'استكشف الكرة الأرضية',
    step2Desc: 'اسحب للتدوير، مرر للتكبير. خطوط كواكبك معروضة على الكرة الأرضية. كل خط ملون يمثل مزيج كوكب-زاوية.',
    step3: 'انقر على المدن',
    step3Desc: 'المدن القريبة من خطوطك تظهر في اللوحة السفلية. انقر على أي مدينة للحصول على قراءة مفصلة لطاقة الكوكب هناك.',
    step4: 'فلتر حسب الكوكب',
