    step5: 'اقرأ خريطتك الفلكية',
    step5Desc: 'انقر على "خريطة الولادة" لعرض مواقع كواكبك. انتقل إلى "الشخصية" لقراءات مفصلة — انقر على أي كوكب لمعرفة معناه في برجك وبيتك.',

    // Guide - FAQ
    faqTitle: 'الأسئلة الشائعة',
    faq1Q: 'هل أحتاج لمعرفة وقت ولادتي الدقيق؟',
    faq1A: 'نعم. وقت ولادتك يحدد الطالع ورؤوس البيوت، التي تُزيح خطوطك بشكل كبير. إذا كنت لا تعرف وقتك الدقيق، تحقق من شهادة ميلادك أو اتصل بمستشفى الولادة.',
    faq2Q: 'ما مدى القرب الذي أحتاجه من خط؟',
    faq2A: 'التأثير أقوى ضمن 1-2° من الخط (حوالي 100-200 كم). نعرض المدن حتى 3.5° بعيدًا، مع تناقص قوة الإشارة مع المسافة.',
    faq3Q: 'هل يمكنني العيش على خط "حذر"؟',
    faq3A: 'يعتمد على الكوكب. خطوط زحل تجلب الثقل والتقدم البطيء. خطوط المريخ تخلق صراعات. خطوط نبتون تذيب الوضوح. خطوط بلوتو تفرض تحولًا مكثفًا. الزيارات القصيرة تعلم دروسًا قيّمة؛ الإقامات الطويلة تتطلب وعيًا ذاتيًا عميقًا.',
    faq4Q: 'ما الفرق بين عرض الكرة الأرضية والخريطة؟',
    faq4A: 'عرض الكرة الأرضية يُظهر الأرض بالأبعاد الثلاثية للسياق المكاني. عرض الخريطة يفرد الإسقاط بشكل مسطح، مما يسهّل تتبع الخطوط عبر القارات ومقارنة المناطق.',
    faq5Q: 'هل يستند هذا إلى علم فلك حقيقي؟',
    faq5A: 'نعم. يتم حساب مواقع الكواكب باستخدام خوارزميات فلكية عالية الدقة (astronomy-engine)، مماثلة لبيانات التقويم الفلكي البحثية. ثم تطبق الخرائط الفلكية التفسير الفلكي على هذه المواقع.',

