    // Guide - Overview
    whatIsNN: '네이탈 내비게이터란',
    whatIsNNBody: '네이탈 내비게이터는 출생 차트를 지구 위에 매핑하는 아스트로카토그래피 도구입니다. 행성 위치와 에너지적으로 조화되는 도시와 지역을 밝혀주며, 강점이 증폭되는 곳과 도전이 생길 수 있는 곳을 보여줍니다.',
    whatIsAstro: '아스트로카토그래피란',
    whatIsAstroBody1: '아스트로카토그래피(위치 점성술)는 출생 차트에서 각 행성이 상승, 하강, 남중 또는 최저점에 있었던 위치를 계산하고, 그 위치를 라인으로 지구 위에 투영합니다. 이 라인 근처에서 살거나 여행하면 해당 행성의 에너지가 삶에서 활성화됩니다.',
    whatIsAstroBody2: '출생 차트는 태어난 순간 하늘의 스냅샷입니다. 그 시점의 태양, 달, 행성의 위치가 성격 특성, 강점, 삶의 주제를 정의합니다. 아스트로카토그래피는 이 행성 에너지가 지구상 어디에서 가장 강했는지를 물음으로써 이를 확장합니다.',

    // Guide - Lines
    fourLineTypes: '네 가지 라인 유형',
    fourLineTypesIntro: '각 행성은 지구 위에 4개의 라인(각 앵글당 하나)을 생성합니다. 라인 유형은 해당 위치에서 행성 에너지가 어떤 생활 영역을 활성화하는지를 결정합니다.',
    mcLine: '미드헤븐',
    mcLineDesc: '행성이 남중하는 곳 — 최고점. 커리어, 사회적 평판, 야망을 활성화합니다. 가장 가시적이고 외향적인 에너지입니다.',
    icLine: '네이디어',
    icLineDesc: '행성이 지평선 아래 최저점에 있는 곳. 가정생활, 감정적 뿌리, 내면의 안정감을 활성화합니다. 깊고 사적인 에너지입니다.',
    ascLine: '어센던트',
    ascLineDesc: '행성이 동쪽 지평선에서 떠오르던 곳. 정체성, 자기 표현, 첫인상을 활성화합니다. 개인적이고 신체적인 에너지입니다.',
    dcLine: '디센던트',
    dcLineDesc: '행성이 서쪽 지평선에서 지던 곳. 파트너십, 대인 관계, 협력을 활성화합니다. 대인적 에너지입니다.',
    lineFootnote: 'MC와 IC는 수직 자오선(극에서 극)입니다. ASC와 DC는 지평선을 따르는 곡선입니다.',

    // Guide - Planets
    planetaryEnergies: '행성 에너지',
    planetaryEnergiesIntro: '각 행성은 특정 삶의 주제를 관장합니다. 행성 라인 근처에 살거나 방문하면 해당 행성의 에너지가 관련 생활 영역에서 증폭됩니다.',

    // Guide - Zones
    zoneClassification: '구역 분류',
    zoneClassificationIntro: '라인 근처의 도시는 행성의 전통적 특성에 따라 세 구역으로 분류됩니다. 절대적 법칙이 아닌 안내로 활용하세요.',
    thriveZoneDesc: '길성 행성 라인 — 태양(활력, 인정), 달(감정적 소속감), 금성(사랑, 아름다움), 목성(행운, 확장). 각 행성은 앵글에 따라 다른 강점을 활성화합니다.',
    neutralZoneDesc: '혼합 에너지 라인 — 수성(소통, 지성) 및 일부 화성/토성/천왕성 앵글. 효과는 미묘하며 의식적인 관여에 달려 있습니다.',
    cautionZoneDesc: '도전적 행성 라인 — 토성(제한), 화성(갈등), 해왕성(혼란), 명왕성(권력 투쟁) 및 특정 천왕성 앵글(불안정). 단기 방문은 교훈이 될 수 있지만 장기 체류는 자각이 필요합니다.',

    // Guide - How to use
    howToUse: '사용 방법',
    step1: '차트 만들기',
    step1Desc: '가입하고 정확한 출생 날짜, 시간, 장소를 입력하세요. 정확도가 중요합니다 — 15분의 차이로도 라인이 이동합니다.',
    step2: '지구본 탐색',
    step2Desc: '드래그로 회전, 스크롤로 확대/축소하세요. 행성 라인이 지구 위에 투영됩니다. 각 색상의 라인은 행성과 앵글의 조합을 나타냅니다.',
    step3: '도시 클릭',
    step3Desc: '라인 근처의 도시가 하단 패널에 표시됩니다. 도시를 클릭하면 해당 위치에서의 행성 에너지에 대한 상세 리딩을 받을 수 있습니다.',
    step4: '행성으로 필터링',
    step4Desc: '왼쪽 사이드바에서 행성을 켜거나 끄고, 펼쳐서 개별 라인을 보고, 번영/중립/주의 구역으로 필터링하세요.',
    step5: '출생 차트 읽기',
    step5Desc: '"출생 차트"를 클릭하여 행성 위치를 확인하세요. "나의 출생 차트"로 전환하면 상세 리딩을 볼 수 있습니다 — 행성을 탭하여 별자리와 하우스에서의 의미를 확인하세요.',

    // Guide - FAQ
    faqTitle: '자주 묻는 질문',
    faq1Q: '정확한 출생 시간을 알아야 하나요?',
    faq1A: '네. 출생 시간이 어센던트와 하우스 커스프를 결정하며, 라인을 크게 이동시킵니다. 정확한 시간을 모르면 출생증명서를 확인하거나 출생 병원에 문의하세요.',
    faq2Q: '라인에서 얼마나 가까워야 하나요?',
    faq2A: '영향은 라인에서 1-2° 이내(약 100-200km)에서 가장 강합니다. 3.5°까지의 도시를 표시하며, 거리에 따라 신호 강도가 감소합니다.',
    faq3Q: '"주의" 라인에서 살 수 있나요?',
    faq3A: '행성에 따라 다릅니다. 토성 라인은 무거움과 더딘 진전을 가져옵니다. 화성 라인은 갈등을 만듭니다. 해왕성 라인은 명확성을 흐리게 합니다. 명왕성 라인은 강렬한 변환을 강요합니다. 단기 방문은 귀중한 교훈이 될 수 있지만, 장기 체류는 깊은 자기 인식이 필요합니다.',
    faq4Q: '지구본 보기와 지도 보기의 차이점은?',
    faq4A: '지구본 보기는 3D로 공간적 맥락을 제공합니다. 지도 보기는 투영을 평면으로 펼쳐 대륙을 가로지르는 라인 추적과 지역 비교가 쉬워집니다.',
    faq5Q: '실제 천문학에 기반하나요?',
    faq5A: '네. 행성 위치는 고정밀 천문 계산 알고리즘(astronomy-engine)을 사용하여 계산되며, 연구 수준의 천문력 데이터에 필적합니다. 아스트로카토그래피는 이 위치에 점성학적 해석을 적용합니다.',

    // Angle info
    mcFull: '메디움 코엘리 (미드헤븐)',
    mcAngleDesc: '출생 시 하늘의 최고점. 커리어, 사회적 평판, 세상이 당신의 성취를 어떻게 보는지를 나타냅니다. MC 라인에서는 직업적으로 힘을 얻고 대중적 인정을 받습니다.',
    icFull: '이뭄 코엘리 (네이디어)',
    icAngleDesc: '지평선 아래의 가장 깊은 지점. 가정, 뿌리, 가족, 내면의 감정 생활을 나타냅니다. IC 라인에서는 깊은 소속감과 감정적 안정을 느낍니다.',
