    // Guide - Overview
    whatIsNN: 'WAT IS NATAL NAVIGATOR',
    whatIsNNBody: 'Natal Navigator is een astrocartografie-tool die je geboortehoroscoop op de globe projecteert. Het onthult welke steden en regio\'s ter wereld energetisch zijn afgestemd op je planetaire posities — en toont waar je sterke punten worden versterkt en waar uitdagingen kunnen ontstaan.',
    whatIsAstro: 'WAT IS ASTROCARTOGRAFIE',
    whatIsAstroBody1: 'Astrocartografie (of locationale astrologie) berekent waar elke planeet in je geboortehoroscoop opkwam, onderging, culmineerde of op het laagste punt stond — en projecteert die posities als lijnen over de globe. Wonen nabij of reizen naar deze lijnen activeert de energie van de planeet in je leven.',
    whatIsAstroBody2: 'Je geboortehoroscoop is een momentopname van de hemel op het exacte moment van je geboorte. De posities van de Zon, Maan en planeten op dat moment bepalen je persoonlijkheidskenmerken, sterke punten en levensthema\'s. Astrocartografie breidt dit uit door te vragen: waar op aarde waren deze planetaire energieen het sterkst?',

    // Guide - Lines
    fourLineTypes: 'DE VIER LIJNTYPEN',
    fourLineTypesIntro: 'Elke planeet produceert vier lijnen op de globe — een voor elke hoek. Het lijntype bepaalt welk levensgebied de energie van de planeet activeert op die locatie.',
    mcLine: 'Medium Coeli',
    mcLineDesc: 'Waar een planeet culmineert — het hoogste punt. Activeert carriere, publieke reputatie en ambitie. De meest zichtbare en naar buiten gerichte energie.',
    icLine: 'Nadir',
    icLineDesc: 'Waar een planeet op het laagste punt onder de horizon staat. Activeert huiselijk leven, emotionele wortels en innerlijke veiligheid. Diepe, prive-energie.',
    ascLine: 'Ascendant',
    ascLineDesc: 'Waar een planeet opkwam aan de oostelijke horizon. Activeert identiteit, zelfexpressie en eerste indrukken. Persoonlijke en fysieke energie.',
    dcLine: 'Descendant',
    dcLineDesc: 'Waar een planeet onderging aan de westelijke horizon. Activeert partnerschappen, relaties en samenwerking. Interpersoonlijke energie.',
    lineFootnote: 'MC en IC zijn verticale meridiaan lijnen (pool tot pool). ASC en DC zijn gebogen lijnen die de horizon volgen.',

    // Guide - Planets
    planetaryEnergies: 'PLANETAIRE ENERGIEEN',
    planetaryEnergiesIntro: 'Elke planeet beheerst specifieke levensthema\'s. Wanneer je nabij een planetaire lijn woont of deze bezoekt, wordt de energie van die planeet versterkt in het overeenkomstige levensgebied.',

    // Guide - Zones
    zoneClassification: 'ZONECLASSIFICATIE',
    zoneClassificationIntro: 'Steden nabij je lijnen worden ingedeeld in drie zones op basis van de traditionele aard van de planeet. Gebruik ze als richtlijn, niet als absolute regels.',
    thriveZoneDesc: 'Weldadige planetaire lijnen — Zon (vitaliteit, erkenning), Maan (emotioneel thuishoren), Venus (liefde, schoonheid) en Jupiter (geluk, expansie). Elke planeet activeert verschillende sterke punten afhankelijk van de hoek.',
    neutralZoneDesc: 'Lijnen met gemengde energie — Mercurius (communicatie, intellect) en sommige Mars/Saturnus/Uranus hoeken. Effecten zijn subtiel en afhankelijk van bewuste betrokkenheid.',
    cautionZoneDesc: 'Uitdagende planetaire lijnen — Saturnus (beperking), Mars (conflict), Neptunus (verwarring), Pluto (machtsstrijd) en bepaalde Uranus hoeken (instabiliteit). Korte bezoeken kunnen lessen leren; langere verblijven vereisen bewustzijn.',

    // Guide - How to use
    howToUse: 'HOE TE GEBRUIKEN',
    step1: 'Maak je horoscoop',
    step1Desc: 'Meld je aan en voer je exacte geboortedatum, -tijd en -plaats in. Nauwkeurigheid is belangrijk — zelfs 15 minuten kan je lijnen verschuiven.',
    step2: 'Verken de globe',
    step2Desc: 'Sleep om te draaien, scroll om te zoomen. Je planetaire lijnen worden geprojecteerd over de globe. Elke gekleurde lijn vertegenwoordigt een planeet-hoek combinatie.',
    step3: 'Klik op steden',
    step3Desc: 'Steden nabij je lijnen verschijnen in het onderste paneel. Klik op een stad voor een gedetailleerde lezing van wat die planetaire energie daar voor je betekent.',
    step4: 'Filter op planeet',
    step4Desc: 'Gebruik de linkerzijbalk om planeten aan/uit te schakelen, ze uit te vouwen om hun individuele lijnen te zien en te filteren op kracht/neutraal/voorzichtigheidszones.',
    step5: 'Lees je geboortehoroscoop',
    step5Desc: 'Klik op "Geboortehoroscoop" om je planetaire posities te zien. Schakel over naar "Je Geboortehoroscoop" voor gedetailleerde lezingen — tik op een planeet om te zien wat het betekent in je teken en huis.',

    // Guide - FAQ
    faqTitle: 'VEELGESTELDE VRAGEN',
    faq1Q: 'Moet ik mijn exacte geboortetijd weten?',
    faq1A: 'Ja. Je geboortetijd bepaalt de Ascendant en huiscuspen, die je lijnen aanzienlijk verschuiven. Als je je exacte tijd niet weet, controleer je geboorteakte of neem contact op met het ziekenhuis.',
    faq2Q: 'Hoe dicht bij een lijn moet ik zijn?',
    faq2A: 'De invloed is het sterkst binnen 1-2° van een lijn (ongeveer 100-200 km). We tonen steden tot 3,5° afstand, waarbij de signaalsterkte afneemt met de afstand.',
    faq3Q: 'Kan ik op een "voorzichtigheidslijn" wonen?',
    faq3A: 'Het hangt af van de planeet. Saturnuslijnen brengen zwaarte en traag voortgang. Marslijnen creeren conflict. Neptunuslijnen lossen helderheid op. Plutolijnen dwingen intense transformatie af. Korte bezoeken kunnen waardevolle lessen leren; langere verblijven vereisen diep zelfbewustzijn.',
    faq4Q: 'Wat is het verschil tussen globe- en kaartweergave?',
    faq4A: 'Globeweergave toont de Aarde in 3D voor ruimtelijke context. Kaartweergave vouwt de projectie plat open, waardoor het makkelijker is om lijnen over continenten te volgen en regio\'s te vergelijken.',
    faq5Q: 'Is dit gebaseerd op echte astronomie?',
    faq5A: 'Ja. Planetaire posities worden berekend met astronomische algoritmen van hoge precisie (astronomy-engine), vergelijkbaar met ephemeridegegevens van onderzoekskwaliteit. Astrocartografie past vervolgens astrologische interpretatie toe op deze posities.',

